import os, signal, sys, time
name, mode = sys.argv[1], sys.argv[2]
uid = int(sys.argv[3]) if len(sys.argv) > 3 else None
if mode == "session":
    os.setsid()
log = os.open(name + ".log", os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o666)
ready = os.open(name + ".ready", os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o666)
if uid is not None:
    os.setgroups([]); os.setgid(uid); os.setuid(uid)
def handler(sig, frame):
    os.write(log, (signal.Signals(sig).name[3:] + "\n").encode())
    if sig == signal.SIGTERM:
        os._exit(0)
for s in (signal.SIGUSR1, signal.SIGUSR2, signal.SIGHUP, signal.SIGTERM):
    signal.signal(s, handler)
os.write(ready, b"1")
end = time.time() + 40
while time.time() < end:
    time.sleep(0.05)

